/**
 * Generated by scaffold-auth-module. Hashes passwords with bcrypt, issues
 * access + refresh JWTs via TokenService, validates refresh tokens against
 * the user's stored refresh token. Designed to work with the canonical
 * SetTokenInterceptor (reads the .accessToken + .refreshToken fields from
 * the returned object and sets cookies, then strips them from the JSON
 * body before responding).
 */
import {
  ConflictException,
  Injectable,
  NotFoundException,
  UnauthorizedException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import * as bcrypt from 'bcrypt';

import { TokenService } from '../../infrastructure/token/token.service';
import { User } from '../user/user.entity';

import { LoginDto } from './dtos/login.dto';
import { SignupDto } from './dtos/signup.dto';
import { user_role } from '../../common/enums/user-role.enum';

const BCRYPT_ROUNDS = 10;

@Injectable()
export class AuthService {
  constructor(
@InjectRepository(User)
    private readonly userRepo: Repository<User>,
    private readonly tokenService: TokenService,
  ) {}

  async signup(dto: SignupDto) {
    const existing = await this.userRepo.findOne({ where: { email: dto.email } });
    if (existing) {
      throw new ConflictException('Account already exists for this email');
    }

    const passwordHash = await bcrypt.hash(dto.password, BCRYPT_ROUNDS);
    const payload: any = {
      email: dto.email,
      fullName: dto.fullName,
      passwordHash: passwordHash,
      // The role is NOT read from the request. `role: dto.role` handed the
      // caller their own privilege level: POST /api/auth/signup with
      // {"role": 99} minted an administrator, from the public internet, with
      // no session and no approval — and 99 is the same code the RolesGuard
      // trusts on every admin endpoint. Signing up makes a student. Instructors
      // and administrators are appointed in the console, which is the whole
      // point of having one.
      role: user_role.STUDENT,
    };
    const created = this.userRepo.create(payload);
    const user = await this.userRepo.save(created);

    return this.issueTokens(user);
  }

  async login(dto: LoginDto) {
    const user = await this.userRepo.findOne({ where: { email: dto.email } });
    if (!user) {
      throw new UnauthorizedException('Invalid credentials');
    }
    // Read the hash off the entity directly. It used to be reached through a double cast, which was
    // never necessary: the entity DECLARES passwordHash, and @Exclude() governs serialization,
    // not the TypeScript type, so Repository<Entity>.findOne already returns it. Four of the six
    // unsafe casts the backend gate counts came from this file, and a template that casts past its
    // own types is what every LLM-written service in the run then imitates.
    const ok = await bcrypt.compare(dto.password, user.passwordHash);
    if (!ok) {
      throw new UnauthorizedException('Invalid credentials');
    }
    return this.issueTokens(user);
  }

  async refresh(refreshToken: string | undefined) {
    if (!refreshToken) {
      throw new UnauthorizedException('Refresh token missing');
    }
    const payload = this.tokenService.verifyRefresh(refreshToken);
    const user = await this.userRepo.findOne({ where: { id: payload.id } });
    if (!user) {
      throw new UnauthorizedException('User not found');
    }
    return this.issueTokens(user);
  }

  async logout(refreshToken: string | undefined) {
    if (refreshToken) {
      // best-effort invalidate; ignore errors
      try { await this.tokenService.revokeRefresh(refreshToken); } catch (_) { /* swallow */ }
    }
  }

  async findMe(userId: string) {
    const user = await this.userRepo.findOne({ where: { id: userId } });
    if (!user) {
      throw new NotFoundException('User not found');
    }
    // Destructuring the entity directly gives `safe` the type Omit<Entity, 'passwordHash'>,
    // which is what the caller wants — the cast this replaced widened it to a bag of unknowns.
    const { passwordHash: _omitted, ...safe } = user;
    return safe;
  }

  /**
   * Returns the user (without password) + accessToken + refreshToken.
   * SetTokenInterceptor reads these fields, sets cookies, then strips
   * them from the JSON body before responding to the client.
   */
  // Accepts the User entity (or User[] from save() overload). Caller flow:
  // signup/login/refresh all hand a single user through — the array form is
  // a TypeORM type quirk that can't actually happen at runtime, but the
  // permissive param type avoids forcing every caller to narrow.
  private async issueTokens(user: any) {
    const u = (Array.isArray(user) ? user[0] : user) as unknown as { id: string; email?: string; role?: string; [k: string]: unknown };
    // `??`, not `||`: role 0 is falsy, so `||` hands whoever holds it the default and RBAC breaks for
    // them. scaffold-jwt-role-nullish-doctor exists to repair exactly this — and it was repairing THIS
    // LINE every run: the doctor runs at node 72, generate-auth-module-final re-asserts the canonical
    // auth module at node 74, and the template put the bug back. The doctor is a net for LLM output;
    // it should never have been catching the template.
    const payload = { id: u.id, email: String(u.email ?? ''), role: u.role ?? 'user' };
    const accessToken = this.tokenService.signAccess(payload);
    const refreshToken = this.tokenService.signRefresh(payload);
    const { passwordHash: _omitted, ...safe } = u as unknown as { passwordHash?: string; [k: string]: unknown };
    return { user: safe, accessToken, refreshToken };
  }
}
